    fields, field, quoted = [], "", False
    for ch in text:
        if ch == QUOTE:
            quoted = not quoted
            field += ch
        elif ch == SEP and not quoted:
            fields.append(field)
            field = ""
        else:
            field += ch
    if quoted:
        raise ValueError("unclosed quote")
    fields.append(field)
    result = {}
    for field in fields:
        if not field.strip():
